using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class BlogPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blog", "View"); return AdminDataService.GetList("Blog"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blog", "View"); return AdminDataService.GetDefinitionMetadata("Blog"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Blog", "Delete"); return AdminDataService.Delete("Blog", id); } } }
